      var cr = '', cr2 = ''; try { var a = document.querySelector('.aph-avatar'); if (a && a.src) { cr = '<div class="cw"><img alt="" src="' + a.src + '"></div>'; cr2 = '<img alt="" src="' + a.src + '">'; } } catch (e) { }
